function unwrap(input) {
  let obj = input;
  for (let i = 0; i < 10; i++) {
    if (Array.isArray(obj) && obj.length > 0) { obj = obj[0]; continue; }
    if (obj && typeof obj === 'object' && obj.body !== undefined) {
      const inner = obj.body;
      if (Array.isArray(inner) || (inner && typeof inner === 'object')) { obj = inner; continue; }
    }
    break;
  }
  return obj;
}

const payload = unwrap($input.first().json);
const event = payload.event || {};
const device = payload.device || {};

const eventType = event.type || 'unknown';
const deviceId = device.id || 0;
const deviceName = device.name || 'Vehículo desconocido';
const eventTime = event.eventTime || new Date().toISOString();
const eventAttrs = event.attributes || {};

const typeLabels = {
  'ignitionOn': '🟢 Ignición encendida',
  'ignitionOff': '🔴 Ignición apagada',
  'deviceOnline': '📡 Dispositivo en línea',
  'deviceOffline': '📴 Dispositivo fuera de línea',
  'geofenceEnter': '📍 Entrada a geocerca',
  'geofenceExit': '🚪 Salida de geocerca',
  'alarm': '🚨 Alarma',
  'driverChanged': '👤 Cambio de conductor',
  'media': '📷 Multimedia',
  'maintenance': '🔧 Mantenimiento'
};

let label = typeLabels[eventType];
if (eventType === 'commandResult') {
  const result = (eventAttrs.result || '').toLowerCase();
  if (result.includes('cut off')) label = '🛑 Paro de motor activado';
  else if (result.includes('restore')) label = '✅ Motor restablecido';
  else label = `⚙️ Comando: ${eventAttrs.result || 'sin detalle'}`;
}
if (!label) label = `Evento: ${eventType}`;

let timeStr = '';
try {
  const date = new Date(eventTime);
  timeStr = date.toLocaleString('es-MX', {
    timeZone: 'America/Mexico_City',
    day: '2-digit', month: '2-digit', year: 'numeric',
    hour: '2-digit', minute: '2-digit'
  });
} catch { timeStr = eventTime; }

const message = `*VigilaTeh* 🚗\n\n${label}\n\n📱 ${deviceName}\n🕐 ${timeStr}`;

return [{ json: { eventType, deviceId, deviceName, eventTime, message } }];
